from django.db import migrations, models


def recover_household_themes(apps, schema_editor):
    # Older notes only recorded the round and step. Use a theme when the family
    # has one distinct choice. Otherwise the regular garden theme is the fallback.
    db = schema_editor.connection.alias
    learners = apps.get_model("pilot", "Learner").objects.using(db)
    notes = apps.get_model("pilot", "LessonFeedback").objects.using(db)
    households = learners.values("parent_id").annotate(
        count=models.Count("lesson_theme", distinct=True), theme=models.Min("lesson_theme")
    ).filter(count=1, parent_id__in=notes.values("parent_id"))
    for family in households:
        notes.filter(parent_id=family["parent_id"]).update(preview_settings={"theme": family["theme"]})


